const onAppSelected = () => {
  if (gGeneralPane.isValidHandlerApp(params.handlerApp)) {
    handlerApp = params.handlerApp;

    // Add the app to the type's list of possible handlers.
    handlerInfo.addPossibleApplicationHandler(handlerApp);
  }
  onSelectionDone();
};

